#!/usr/bin/env python3
"""Independent sparse exterior algebra; no producer/SymPy imports."""
from pathlib import Path
import hashlib
import itertools
import json
import resource
import time

resource.setrlimit(resource.RLIMIT_AS, (1024**3, 1024**3))
resource.setrlimit(resource.RLIMIT_CPU, (55, 55))
start = time.monotonic()
ROOT = Path(__file__).resolve().parents[1]
report_path = 'reports/CLASSIFICATION_RANK3_QUADRIC_FORMS_20261107.json'
source = json.loads((ROOT / report_path).read_text())
assert hashlib.sha256((ROOT / 'code/classification_double_quadric.py').read_bytes()).hexdigest() == source['source_sha256']
cert = source['result']['rank3_H_contains_vertex_transverse']
zero = (0, 0, 0, 0)
unit = [tuple(int(i == j) for i in range(4)) for j in range(4)]
pairs = list(itertools.combinations(range(4), 2))
triples = list(itertools.combinations(range(4), 3))

def mons(d):
    result = []
    for k in range(d + 1):
        for ids in itertools.combinations_with_replacement(range(4), k):
            result.append(tuple(ids.count(i) for i in range(4)))
    return result

def plus(a, b, scale=1):
    c = dict(a)
    for m, v in b.items():
        c[m] = c.get(m, 0) + scale*v
        if not c[m]:
            del c[m]
    return c

def times(a, b):
    c = {}
    for ma, va in a.items():
        for mb, vb in b.items():
            m = tuple(x + y for x, y in zip(ma, mb))
            c[m] = c.get(m, 0) + va*vb
    return {m: v for m, v in c.items() if v}

def deriv(p, i):
    return {tuple(x - int(k == i) for k, x in enumerate(m)): v*m[i]
            for m, v in p.items() if m[i]}

def wedge(a, b):
    result = {}
    for ia, pa in a.items():
        for ib, pb in b.items():
            ids = ia + ib
            if len(set(ids)) != len(ids):
                continue
            sign = (-1)**sum(ids[i] > ids[j] for i in range(len(ids)) for j in range(i+1, len(ids)))
            key = tuple(sorted(ids))
            result[key] = plus(result.get(key, {}), times(pa, pb), sign)
    return {k: p for k, p in result.items() if p}

def exterior(a):
    result = {}
    for ids, p in a.items():
        for i in range(4):
            term = wedge({(i,): deriv(p, i)}, {ids: {zero: 1}})
            for key, poly in term.items():
                result[key] = plus(result.get(key, {}), poly)
    return {k: p for k, p in result.items() if p}

Q = {zero: 1, (2, 0, 0, 0): 1, (0, 2, 0, 0): 1}
dQ = {(i,): deriv(Q, i) for i in range(4) if deriv(Q, i)}
qmons, cmon = mons(2), mons(3)
columns = []
for pair in pairs:
    for mon in qmons:
        alpha = {pair: {mon: 1}}
        da, qa = exterior(alpha), wedge(dQ, alpha)
        columns.append([plus(times(Q, da.get(triple, {})), qa.get(triple, {}), -2).get(m, 0)
                        for triple in triples for m in cmon])
D = list(map(list, zip(*columns)))
primitive = []
for i in range(4):
    for mon in mons(1):
        beta = {(i,): {mon: 1}}
        db, qb = exterior(beta), wedge(dQ, beta)
        primitive.append([plus(times(Q, db.get(pair, {})), qb.get(pair, {}), -1).get(m, 0)
                          for pair in pairs for m in qmons])
B = list(map(list, zip(*primitive)))
extra = [Q.get(m, 0) if pair == (0, 1) else 0 for pair in pairs for m in qmons]
E = [row + [extra[i]] for i, row in enumerate(B)]
assert (len(D), len(D[0])) == (140, 90)
assert (len(B), len(B[0])) == (90, 20)
assert (len(E), len(E[0])) == (90, 21)
assert all(sum(x*y for x, y in zip(row, col)) == 0 for row in D for col in zip(*E))

def determinant(a):
    a = [r[:] for r in a]
    sign, previous = 1, 1
    for k in range(len(a)-1):
        if not a[k][k]:
            p = next(i for i in range(k+1, len(a)) if a[i][k])
            a[k], a[p] = a[p], a[k]
            sign = -sign
        pivot = a[k][k]
        for i in range(k+1, len(a)):
            for j in range(k+1, len(a)):
                numerator = pivot*a[i][j]-a[i][k]*a[k][j]
                assert numerator % previous == 0
                a[i][j] = numerator//previous
            a[i][k] = 0
        previous = pivot
    return sign*a[-1][-1]

minor_results = {}
for label, matrix, key, size in [('closure', D, 'closure_minor', 70),
                                ('primitive', B, 'primitive_minor', 19),
                                ('enlarged', E, 'enlarged_image_minor', 20)]:
    m = cert[key]
    assert len(m['rows']) == len(m['columns']) == size
    value = determinant([[matrix[i][j] for j in m['columns']] for i in m['rows']])
    assert value != 0 and str(value) == m['determinant']
    minor_results[label] = {'size': size, 'determinant': str(value)}
kernel_beta = [0]*20
kernel_beta[1] = 2
kernel_beta[7] = 2
assert all(sum(x*y for x, y in zip(row, kernel_beta)) == 0 for row in B)
hashes = {}
for label, matrix in [('D', D), ('B', B), ('enlarged', E)]:
    digest = hashlib.sha256(json.dumps([[str(x) for x in row] for row in matrix]).encode()).hexdigest()
    assert digest == cert['matrix_sha256'][label]
    hashes[label] = digest
output = {'task_id': 'A', 'date': '2026-11-07',
    'source_report': report_path,
    'source_report_sha256': hashlib.sha256((ROOT / report_path).read_bytes()).hexdigest(),
    'source_runner_sha256': source['source_sha256'],
    'independent_algorithm': 'Sparse integer exterior products and derivatives; fraction-free integer Bareiss minors; producer and SymPy are not imported.',
    'Q': '1+u^2+v^2', 'closure_shape': [140, 90],
    'all_D_times_enlarged_zero': True, 'primitive_dQ_kernel_nonzero': True,
    'exact_minor_matches': minor_results, 'matrix_sha256_matches': hashes,
    'exact_closure_rank': 70, 'exact_primitive_rank': 19,
    'exact_enlarged_image_rank': 20, 'closed_space_equals_enlarged_image': True,
    'scope': 'Only the rank-three transverse inverse-form space. Geometric support proof reviewed separately; no other degeneracy strata or global classification asserted.',
    'global_exhaustion_proved': False, 'elapsed_seconds': time.monotonic()-start,
    'resource_limits': {'cpu_seconds': 55, 'address_space_bytes': 1024**3},
    'reviewer_source': Path(__file__).read_text()}
output['reviewer_sha256'] = hashlib.sha256(output['reviewer_source'].encode()).hexdigest()
target = ROOT / 'reports/CLASSIFICATION_RANK3_TRANSVERSE_REVIEW_20261107.json'
with target.open('x') as f:
    json.dump(output, f, ensure_ascii=False, indent=2)
    f.write('\n')
print(json.dumps({'passed': True, 'seconds': output['elapsed_seconds'], 'ranks': [70, 19, 20]}))
